#include <iostream>
#include <stdexcept>

void handler() {
    try {
        throw;                       // 重抛当前异常（保留类型，不切片）
    } catch (const std::exception& e) {
        std::cout << "logged: " << e.what() << '\n';
        throw;                      // 再次重抛给外层
    }
}

int main() {
    try {
        try {
            throw std::runtime_error("orig");
        } catch (const std::exception& e) {
            handler();
        }
    } catch (const std::exception& e) {
        std::cout << "final: " << e.what() << '\n';
    }
}
